import sys
N=int(sys.stdin.readline())
A=list(map(int,sys.stdin.readline().split()))
fac=[]
for a in A:
    d={}
    x=a
    p=2
    while p*p<=x:
        while x%p==0:
            d[p]=d.get(p,0)+1
            x//=p
        p+=1
    if x>1:
        d[x]=d.get(x,0)+1
    fac.append(d)

primes=set().union(*(f.keys() for f in fac))
ans=1
for p in primes:
    exponents=[f.get(p,0) for f in fac]
    dp={0:1}
    for i,e in enumerate(exponents):
        k=i+1  # number of vertices already included
        nd={}
        if e==0:
            for y,v in dp.items():
                nd[y]=v*pow(p,y,MOD)%MOD
        else:
            for y,v in dp.items():
                for delta in (e,-e):
                    z=y+delta
                    if z>=0:
                        ny=z
                        nv=v*pow(p,z,MOD)%MOD
                    else:
                        ny=0
                        nv=v*pow(p,k*(-z),MOD)%MOD
                    nd[ny]=(nd.get(ny,0)+nv)%MOD
        dp=nd
    ans=ans*(sum(dp.values())%MOD)%MOD
print(ans)

