import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]
    limit = max(a)
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p*p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p
    nim = 0
    for v in a:
        count = 0
        while v > 1:
            v //= spf[v]
            count += 1
        nim ^= count
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

