from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            ending[b].append((a, idx))

        first_val = second_val = 0
        first_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for a, idx in ending[right]:
                if a > first_val:
                    second_val = first_val
                    first_val, first_id = a, idx
                elif a > second_val:
                    second_val = a

            total += right - first_val
            if first_id >= 0:
                gains[first_id] += first_val - second_val

        return total + max(gains)

