class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n=len(s)
        choose=[[0]*(n+1) for _ in range(n+1)]
        choose[0][0]=1
        for a in range(1,n+1):
            choose[a][0]=choose[a][a]=1
            prev=choose[a-1]
            row=choose[a]
            for b in range(1,a):
                row[b]=(prev[b-1]+prev[b])%MOD
        ans=0
        for t in range(1,n+1):
            x=t
            steps=0
            while x>1:
                x=x.bit_count()
                steps+=1
            if steps+1>k:
                continue
            ones=0
            cnt=0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem=n-i-1
                    need=t-ones
                    if 0<=need<=rem:
                        cnt+=choose[rem][need]
                    ones+=1
            ans=(ans+cnt)%MOD
