from itertools import product

def alg(u,d,x):
 n=len(u)
 def f(h):
  lo=max(0,h-d[0]);hi=min(u[0],h)
  for i in range(1,n):
   lo=max(max(0,h-d[i]),lo-x);hi=min(min(u[i],h),hi+x)
   if lo>hi:return False
  return lo<=hi
 l=0;r=min(a+b for a,b in zip(u,d))
 while l<r:
  m=(l+r+1)//2
  if f(m):l=m
  else:r=m-1
 return sum(u)+sum(d)-n*l

def brute(u,d,x):
 n=len(u); best=10**9
 for h in range(min(a+b for a,b in zip(u,d))+1):
  for a in product(*[range(min(v,h)+1) for v in u]):
