from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        remaining = list(range(1, n + 1))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count_completions(odds: int, evens: int, first_parity: int, length: int) -> int:
            slots_first = (length + 1) // 2
            slots_other = length // 2
            if first_parity == 1:
                need_odds, need_evens = slots_first, slots_other
            else:
                need_odds, need_evens = slots_other, slots_first
            if odds != need_odds or evens != need_evens:
                return 0
            return fact[odds] * fact[evens]

        result = []
        previous_parity = None
        while remaining:
            chosen = None
            odd_count = sum(x % 2 for x in remaining)
            for value in remaining:
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue
                odds = odd_count - (parity == 1)
                evens = len(remaining) - odd_count - (parity == 0)
                completions = count_completions(odds, evens, 1 - parity, len(remaining) - 1)
                if k > completions:
                    k -= completions
                else:
                    chosen = value
                    break
            if chosen is None:
                return []
            result.append(chosen)
            remaining.remove(chosen)
            previous_parity = chosen % 2
        return result

