class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for p in range(1, n):
            powers[p] = powers[p - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if i != j:
                c = (c + powers[j]) % k
            coeff.append(c)

        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            old = suffix[i + 1]
            mask = 0
            for r in range(k):
                if old >> r & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * coeff[i]) % k)
            suffix[i] = mask

        digits = ['0'] * n
        rem = 0
        for i in range(m):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-(rem + d * coeff[i])) % k
                if suffix[i + 1] >> need & 1:
                    digits[i] = str(d)
                    digits[n - 1 - i] = str(d)
                    rem = (rem + d * coeff[i]) % k
                    break
        return ''.join(digits)

