from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        # nxt[i] is the first index to the right whose value is greater
        # than nums[i]. Prefix maxima remain nums[i] up to nxt[i] - 1.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        log = n.bit_length()
        ancestor = [[n] * n for _ in range(log)]
        block_cost = [[0] * n for _ in range(log)]
        for i in range(n):
            ancestor[0][i] = nxt[i]
            block_cost[0][i] = nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])

        for p in range(1, log):
            prev_ancestor = ancestor[p - 1]
            prev_cost = block_cost[p - 1]
            for i in range(n):
                mid = prev_ancestor[i]
                if mid < n:
                    ancestor[p][i] = prev_ancestor[mid]
                    block_cost[p][i] = prev_cost[i] + prev_cost[mid]
                else:
                    block_cost[p][i] = prev_cost[i]

        def cost(left: int, right: int) -> int:
            current = left
            total = 0
            for p in range(log - 1, -1, -1):
                end = ancestor[p][current]
                if end <= right:
                    total += block_cost[p][current]
                    current = end
            total += nums[current] * (right + 1 - current) - (pref[right + 1] - pref[current])
            return total

        answer = 0
        for left in range(n):
            lo, hi = left, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(left, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - left + 1
        return answer

