import sys
from functools import lru_cache

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m, l = d[:3]
    p = 3
    vals = d[p:p + n]
    p += n
    vals += d[p:p + m]
    p += m
    vals += d[p:p + l]
    allmask = (1 << len(vals)) - 1

    @lru_cache(None)
    def win(t, a, turn):
        hand = t if turn == 0 else a
        other = a if turn == 0 else t
        if not hand:
            return False
        h = hand
        while h:
            bit = h & -h
            h -= bit
            x = bit.bit_length() - 1
            rem = hand ^ bit

            # Play the card without taking another card.
            if turn == 0:
                if not win(rem, other, 1):
                    return True
            else:
                if not win(other, rem, 0):
                    return True

            # Or take any lower-valued card from the table.
            cand = (allmask ^ (hand | other)) | bit
            while cand:
                b = cand & -cand
                cand -= b
                y = b.bit_length() - 1
                if vals[y] < vals[x]:
                    if turn == 0:
                        if not win(rem | b, other, 1):
                            return True
                    else:
                        if not win(other, rem | b, 0):
                            return True
        return False

    takahashi = (1 << n) - 1
    aoki = ((1 << (n + m)) - 1) ^ takahashi
    print('Takahashi' if win(takahashi, aoki, 0) else 'Aoki')

if __name__ == '__main__':
    main()

