class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        literals = [x for x in parts if x]
        if not literals:
            return 0

        def occurrences(t):
            m = len(t)
            if m > len(s):
                return []
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == m:
                        out.append(i - m + 1)
                        j = pi[j - 1]
            return out

        occ = [occurrences(t) for t in literals]
        if any(not positions for positions in occ):
            return -1

        best = len(s) + 1
        for last_start in occ[-1]:
            end = last_start + len(literals[-1])
            bound = last_start
            possible = True
            for k in range(len(literals) - 2, -1, -1):
                idx = bisect_right(occ[k], bound - len(literals[k])) - 1
                if idx < 0:
                    possible = False
                    break
                bound = occ[k][idx]
            if possible:
                best = min(best, end - bound)
        return -1 if best == len(s) + 1 else best

