from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        post = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                post.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        pos = [0] * n
        sub = [1] * n
        chars = []
        for i, x in enumerate(post):
            pos[x] = i
            chars.append(s[x])
            if parent[x] != -1:
                sub[parent[x]] += sub[x]

        text = ''.join(chars)
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for x in range(n):
            end = pos[x]
            start = end - sub[x] + 1
            length = sub[x]
            if length % 2:
                center = (start + end) // 2
                answer[x] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[x] = even[center] >= length // 2
        return answer

