from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # a1/b1 are the best totals ending in A/B at the previous hour;
        # a2/b2 are those from two hours earlier.
        a2 = b2 = 0
        a1, b1 = energyDrinkA[0], energyDrinkB[0]

        for i in range(1, len(energyDrinkA)):
            a = energyDrinkA[i] + max(a1, b2)
            b = energyDrinkB[i] + max(b1, a2)
            a2, b2 = a1, b1
            a1, b1 = a, b

