import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n < 0 or m < 0:
            return -1
        lo = 10 ** (len(str(n)) - 1)
        hi = 10 ** len(str(n))
        if not (lo <= m < hi) or len(str(n)) != len(str(m)):
            return -1
        prime = bytearray(b'\x01') * hi
        if hi > 0: prime[0] = 0
        if hi > 1: prime[1] = 0
        for p in range(2, int((hi-1)**0.5)+1):
            if prime[p]:
                prime[p*p:hi:p] = b'\x00' * (((hi-1-p*p)//p)+1)
        if prime[n] or prime[m]:
            return -1
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            place = 1
            while place < hi:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if y < hi and not prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, 10**30):
                            dist[y] = nc
                            heapq.heappush(pq, (nc, y))
                if digit > 0:
                    y = x - place
                    if y >= lo and not prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, 10**30):
                            dist[y] = nc
                            heapq.heappush(pq, (nc, y))
                place *= 10
        return -1

