from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z-array of the full sequence: z[i] is LCP(nums, nums[i:]).
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z0[i] = min(right - i, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] > right:
                left, right = i, i + z0[i]

        answer = 0
        for i in range(1, n - 1):
            # Split positions: first part ends at i; second ends at j.
            if z0[i] >= i:
                answer += n - i - 1
                continue

            # Z-array for nums[i:]. At offset d, it gives LCP(nums[i:], nums[i+d:]).
            m = n - i
            z = [0] * m
            left = right = 0
            for d in range(1, m):
                if d < right:
                    z[d] = min(right - d, z[d - left])
                while d + z[d] < m and nums[i + z[d]] == nums[i + d + z[d]]:
                    z[d] += 1
                if d + z[d] > right:
                    left, right = d, d + z[d]

            # d=j-i must be at least 1, and the third part must be nonempty.
            for d in range(1, m):
                if z[d] >= d:
                    answer += 1
        return answer

