class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z0[i] = min(right - i, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] > right:
                left, right = i, i + z0[i]

        answer = 0
        for i in range(1, n - 1):
            m = n - i
            z = [0] * m
            left = right = 0
            for d in range(1, m):
                if d < right:
                    z[d] = min(right - d, z[d - left])
                while d + z[d] < m and nums[i + z[d]] == nums[i + d + z[d]]:
                    z[d] += 1
                if d + z[d] > right:
                    left, right = d, d + z[d]
            first_matches = z0[i] >= i
            for d in range(1, m):
                second_matches = z[d] >= d
                if second_matches or (first_matches and d >= i):
                    answer += 1
        return answer

