class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z0[i] is the LCP of nums and nums[i:].
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z0[i] = min(right - i, z0[i - left])
