                z0[i] += 1
            if i + z0[i] > right:
                left, right = i, i + z0[i]

        answer = 0
        for i in range(1, n - 1):
            m = n - i
            first_matches = z0[i] >= i
            # For lengths d >= i, first-prefix condition applies. Count these
            # directly; only inspect shorter second parts for the other condition.
            if first_matches:
                answer += max(0, n - 2 * i)
            limit = min(i, m)
            z = [0] * limit
            left = right = 0
            for d in range(1, limit):
                if d < right:
                    z[d] = min(right - d, z[d - left])
                while d + z[d] < m and nums[i + z[d]] == nums[i + d + z[d]]:
                    z[d] += 1
                if d + z[d] > right:
                    left, right = d, d + z[d]
                if z[d] >= d:
                    answer += 1
        return answer

