import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    s, t = data[1].decode(), data[2].decode()
    if s == t:
        print('Yes')
        return
    if abs(len(s) - len(t)) > 1:
        print('No')
        return
    if len(s) == len(t):
        mismatches = 0
        for a, b in zip(s, t):
            if a != b:
                mismatches += 1
                if mismatches > 1:
                    break
        print('Yes' if mismatches <= 1 else 'No')
        return
    short, long = (s, t) if len(s) < len(t) else (t, s)
    i = j = skips = 0
    while i < len(short) and j < len(long):
        if short[i] == long[j]:
            i += 1
            j += 1
        else:
            skips += 1
            j += 1
            if skips > 1:
                break
    # Any unmatched final character in long is the one insertion/deletion.
    print('Yes' if skips <= 1 else 'No')

if __name__ == '__main__':
    main()

