from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            ndp = [neg] * (m + 1)
            reward = 1 if i in targets else 0
            for j in range(m + 1):
                if dp[j] != neg:
                    # Leave this character unused; if allowed, remove it.
                    ndp[j] = max(ndp[j], dp[j] + reward)
                    # Or preserve it as the next character of the pattern.
                    if j < m and ch == pattern[j]:
                        ndp[j + 1] = max(ndp[j + 1], dp[j])
            dp = ndp

        return dp[m]

