from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if threshold < 1:
            return -1
        rev = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            rev[b].append((a, w))
            weights.append(w)
        weights = sorted(set(weights))

        def reachable(limit):
            seen = [False] * n
            seen[0] = True
            q = [0]
            for v in q:
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        q.append(u)
            return len(q) == n

        if not weights or not reachable(weights[-1]):
            return -1
        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

