from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        # State is the colors chosen for the current outer pair (left, right).
        dp = [[INF] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            for pa in range(3):
                for pb in range(3):
                    base = dp[pa][pb]
                    if base == INF:
                        continue
                    for a in range(3):
                        if a == pa:
                            continue
                        for b in range(3):
                            if b == pb or b == a:
                                continue
                            val = base + cost[i][a] + cost[n - 1 - i][b]
                            if val < ndp[a][b]:
                                ndp[a][b] = val
            dp = ndp
        return min(min(row) for row in dp)

