class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowel_bit = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        n = len(word)
        ans = 0
        for left in range(n):
            mask = 0
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                bit = vowel_bit.get(ch)
                if bit is None:
                    consonants += 1
                    if consonants > k:
                        break
                else:
                    mask |= bit
                if consonants == k and mask == 31:
                    ans += 1
        return ans

