from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = {tuple(p) for p in points}
        xs = sorted({p[0] for p in points})
        ys = sorted({p[1] for p in points})
        best = -1
        for i, x1 in enumerate(xs):
            for x2 in xs[i + 1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j + 1:]:
                        corners = ((x1, y1), (x1, y2), (x2, y1), (x2, y2))
                        if not all(p in pts for p in corners):
                            continue
                        if any(x1 <= x <= x2 and y1 <= y <= y2
                               for x, y in pts):
                            # Rectangle contains its four corners, so count separately.
                            pass
                        contained = sum(x1 <= x <= x2 and y1 <= y <= y2 for x, y in pts)
                        if contained == 4:
                            best = max(best, (x2 - x1) * (y2 - y1))
        return best

